    {
      "path": "pyproject.toml",
      "content": "[project]\nname = \"everos\"\nversion = \"1.6.0\"\ndescription = \"EverOS — local-first markdown memory framework for AI agents and user chats; lightweight, dev-friendly, small-team\"\nlicense = {text = \"Apache-2.0\"}\nreadme = \"README.md\"\nrequires-python = \">=3.12\"\nauthors = [\n    {name = \"EverMind AI\"},\n]\nkeywords = [\"memory\", \"ai-agent\", \"markdown\", \"lancedb\", \"rag\", \"everos\"]\nclassifiers = [\n    \"Development Status :: 5 - Production/Stable\",\n    \"Intended Audience :: Developers\",\n    \"License :: OSI Approved :: Apache Software License\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Topic :: Scientific/Engineering :: Artificial Intelligence\",\n    \"Typing :: Typed\",\n]\n\ndependencies = [\n    # Core data validation & config\n    \"pydantic>=2.7.1\",\n    \"pydantic-settings>=2.0.0\",\n\n    # Storage stack (md-first three-piece set)\n    # Upper bound: 0.35.0 embeds lance-rust v9 (large storage/encoding jump, not\n    # yet stable-released). 0.32-0.34 carry a compaction offset-overflow regression\n    # (lance-format/lance#7653); we run 0.34.0 safely via the with_position=False\n    # FTS workaround. Do not float past 0.34.x until 0.35 has been validated under\n    # sustained churn (bounded + reclaimable index dir, no compaction crash) — see\n    # docs/cascade_runbook.md. Never widen this floor back below 0.34 (older lance\n    # cannot read v8 data).\n    \"lancedb>=0.34.0,<0.35.0\",    # Vector + BM25 + scalar filter (Arrow-based)\n    # Floor, not a new package: lancedb pulls pyarrow in anyway. 25.0.1 stops\n    # the per-value `import pytz` attempt in to_pylist() (24 walked sys.path\n    # for every tz-aware timestamp) and materialises rows without a Scalar\n    # per element; 25.0.0 lacks the latter and has a mimalloc exit crash.\n    \"pyarrow>=25.0.1\",\n    \"aiosqlite>=0.20.0\",          # Async SQLite driver (used by SA async engine)\n    \"sqlmodel>=0.0.22\",           # ORM (Pydantic + SQLAlchemy 2.0 async)\n    \"alembic>=1.13.0\",            # SQLite schema migrations\n    \"greenlet>=3.0\",              # Required by SQLAlchemy async\n\n    # LLM & embedding (one provider per file pattern)\n    # <3: openai 3.x (2026-09-24) moved to the httpx 1.0 pre-release line and its\n    # client raises AttributeError on every request; 2.x is what the lock tests.\n    \"openai>=1.0.0,<3\",\n\n    # Markdown / file system\n    \"PyYAML>=6.0\",                # YAML frontmatter parsing\n    \"watchdog>=4.0.0\",            # Cross-platform file system events (cascade daemon)\n\n    # Web framework (entrypoints/api)\n    \"fastapi>=0.104.0\",\n    \"python-multipart>=0.0.7\",    # Required by FastAPI for Form / UploadFile endpoints\n    \"uvicorn[standard]>=0.24.0\",\n\n    # Observability (core/observability)\n    \"structlog>=24.0.0\",\n    \"prometheus-client>=0.20.0\",\n\n    # CLI + TUI\n    \"typer>=0.12.0\",\n    # click is a transitive dep of uvicorn today, but our CLI raises\n    # ``click.exceptions.Abort`` directly (e.g. tests that inject aborts)\n    # and typer 0.15+ vendored a copy of click under ``typer._click`` — so\n    # the two classes are DIFFERENT even though users only ever see\n    # ``typer.Abort``. We depend on the standalone click package so\n    # ``click.exceptions.Abort`` stays importable and both classes are\n    # covered in the Ctrl-C catch (see backfill exit-130 path).\n    \"click>=8.1\",\n    \"textual>=8.2.7\",\n\n    # Tokenization (BM25 Chinese support)\n    \"jieba>=0.42.1,<1.0\",\n\n    # OME (Offline Memory Evolution) async scheduler & file I/O\n    \"apscheduler>=3.10.4,<4.0\",   # async strategy scheduler chassis\n    \"portalocker>=2.8.2\",          # cross-platform file lock for single-engine guard\n    # Windows only: the MSVC C++ runtime (msvcp140.dll et al.) that greenlet's\n    # wheel links against and a stock Windows does not ship. It lands in\n    # sys.prefix; everos/__init__.py registers that dir with the DLL loader.\n    \"msvc-runtime>=14.44; sys_platform == 'win32'\",\n    \"watchfiles>=0.21.0\",          # native fs watcher for config hot reload\n    \"anyio>=4.0\",                  # Async file I/O (anyio.Path, to_thread.run_sync) for the markdown layer\n\n    # Algorithm library (everalgo monorepo, published on PyPI).\n    #\n    # All eight everalgo packages (the four below, the three transitive ones\n    # after them, and everalgo-parser in the `multimodal` extra) ship on one\n    # contract line -- currently the 2026-10-13 line, built on everalgo-core\n    # 0.6.0's `LLMClient.achat` contract. The packages declare loose ranges on\n    # one another, so a fresh `pip install everos` would otherwise mix lines\n    # the suite has never run together. Pin every one with `==` and raise them\n    # together, with a run of the release smoke against a PyPI-resolved install.\n    \"everalgo-user-memory==0.9.0rc4\",\n    \"everalgo-agent-memory==0.6.0rc3\",\n    \"everalgo-rank==0.5.0rc3\",\n    \"everalgo-knowledge==0.3.0rc2\",\n    \"everalgo-boundary==0.4.1\",\n    \"everalgo-core==0.6.0\",\n    \"everalgo-clustering==0.3.0rc2\",\n]\n\n[project.optional-dependencies]\nmultimodal = [\"everalgo-parser[svg]==0.3.0rc2\"]  # [svg] bundles cairosvg → SVG works by default\n# Native OpenTelemetry tracing export. Optional — EverOS never imports these\n# unless [observability] is enabled. Install with: pip install everos[otel]\notel = [\n    \"opentelemetry-sdk>=1.27.0\",\n    \"opentelemetry-exporter-otlp-proto-http>=1.27.0\",\n]\nmilvus = [\"pymilvus>=3.0.0\"]\n\n[project.urls]\nHomepage = \"https://evermind.ai\"\nRepository = \"https://github.com/EverMind-AI/EverOS\"\nChangelog = \"https://github.com/EverMind-AI/EverOS/blob/main/CHANGELOG.md\"\n\"Bug Tracker\" = \"https://github.com/EverMind-AI/EverOS/issues\"\n\n[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/everos\"]\n\n# ``env.template`` lives at src/everos/templates/env.template and is\n# auto-included via ``packages``. ``everos init`` reads it through\n# ``importlib.resources``. No force-include needed.\n\n# sdist uses an include-whitelist (not exclude) so we don't accidentally ship\n# things like CLAUDE.md, .claude/, CI configs, or IDE settings. New top-level\n# files default to NOT-shipped — you have to opt them in here.\n#\n# exclude is kept as belt-and-suspenders for build artefacts that CI generates\n# inside the project tree (UV_CACHE_DIR=.uv-cache in .gitlab-ci.yml).\n[tool.hatch.build.targets.sdist]\ninclude = [\n    \"/src\",\n    \"/tests\",\n    \"/docs\",\n    \"/pyproject.toml\",\n    \"/README.md\",\n    \"/QUICKSTART.md\",\n    \"/CHANGELOG.md\",\n    \"/CONTRIBUTING.md\",\n    \"/CODE_OF_CONDUCT.md\",\n    \"/SECURITY.md\",\n    \"/ACKNOWLEDGMENTS.md\",\n    \"/CITATION.md\",\n    \"/LICENSE\",\n    \"/NOTICE\",\n    \"/config.example.toml\",\n]\nexclude = [\".uv-cache\", \".venv\"]\n\n[project.scripts]\neveros = \"everos.entrypoints.cli.main:app\"\n\n# ───────────────────────────────────────────────────────────────────────────────\n# Tooling\n# ───────────────────────────────────────────────────────────────────────────────\n\n[tool.ruff]\nline-length = 88\ntarget-version = \"py312\"\nextend-exclude = [\"src_old\"]\n\n[tool.ruff.lint]\nselect = [\"E\", \"F\", \"I\", \"N\", \"UP\", \"B\", \"SIM\", \"ASYNC\", \"RUF\"]\nignore = [\n    \"RUF001\",  # ambiguous Unicode in strings (intentional × – symbols)\n    \"RUF002\",  # ambiguous Unicode in docstrings\n    \"RUF003\",  # ambiguous Unicode in comments\n    \"RUF012\",  # mutable class attribute default (SQLModel requires this)\n]\n\n[tool.ruff.lint.per-file-ignores]\n# The four dataset adapters hold the answer and judge prompts as multi-line string\n# literals, copied byte-for-byte from each benchmark's reference harness. Rewrapping one\n# changes what the model is shown and so changes the score, which is the opposite of what\n# this code is for. Every long line in these four files is inside such a literal --\n# nothing outside one is exempted, and no other file under benchmarks/ is.\n\"benchmarks/adapters/locomo.py\" = [\"E501\"]\n\"benchmarks/adapters/longmemeval.py\" = [\"E501\"]\n\"benchmarks/adapters/subtlememory.py\" = [\"E501\"]\n\"benchmarks/adapters/evermembench.py\" = [\"E501\"]\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\npython_functions = [\"test_*\"]\nasyncio_mode = \"auto\"\naddopts = \"-v --tb=short -m 'not slow and not live_llm'\"\nfilterwarnings = [\n    \"error\",\n    # tzlocal (via APScheduler, imported by the OME engine): a container with no\n    # /etc/timezone and no /etc/localtime warns and falls back to UTC. Under `error`\n    # that aborts COLLECTION for every test that imports the app -- measured at 50\n    # files here -- so `make test` fails on a clean container for a reason unrelated\n    # to any test. The fallback is already what this project wants: the display\n    # timezone comes solely from EVEROS_MEMORY__TIMEZONE, never from the OS (see\n    # .claude/rules/datetime-handling.md), so tzlocal's guess is never read.\n    \"ignore:Can not find any timezone configuration:UserWarning\",\n    # jieba 0.42.1: unescaped backslashes in regex strings (upstream\n    # unmaintained; no fix available).  Python 3.12 emits\n    # SyntaxWarning for invalid escape sequences.\n    \"ignore:invalid escape sequence:SyntaxWarning\",\n    # aiosqlite teardown: connection-worker thread and Connection.__del__\n    # raise after pytest closes the event loop.  Upstream issue\n    # (aiosqlite + pytest-asyncio); we cannot fix their lifecycle.\n    \"ignore:Exception in thread.*_connection_worker_thread:pytest.PytestUnhandledThreadExceptionWarning\",\n    # aiosqlite + asyncio teardown: Connection.__del__ and\n    # BaseEventLoop.__del__ fire after pytest closes the event loop.\n    # Upstream lifecycle issue; we cannot fix their cleanup order.\n    \"ignore:Exception ignored.*:pytest.PytestUnraisableExceptionWarning\",\n]\nmarkers = [\n    \"slow: runs that take >=10s (regardless of dependency); CI default excludes these. Run with `pytest -m slow`.\",\n    \"live_llm: requires real LLM / embedder / reranker credentials from .env; burns tokens. CI default excludes. Run with `pytest -m live_llm`.\",\n]\n\n[tool.coverage.run]\nsource = [\"src/everos\"]\nbranch = true\nomit = [\"**/__init__.py\"]\n\n[tool.coverage.report]\nfail_under = 80\nshow_missing = true\nexclude_lines = [\n    \"if TYPE_CHECKING:\",\n    \"@abstractmethod\",\n    \"pragma: no cover\",\n]\n\n[tool.importlinter]\nroot_packages = [\"everos\"]\n# Annotation-only imports under ``if TYPE_CHECKING:`` never run, so they\n# cannot couple layers at runtime; contracts check runtime imports only.\nexclude_type_checking_imports = true\n# External packages enter the graph so ``no-bypass-facade`` can name\n# structlog / logging / opentelemetry.\ninclude_external_packages = true\n\n[[tool.importlinter.contracts]]\n# Dependency inversion (stage 2b): the domain declares storage ports in\n# ``everos.memory.ports`` and ``everos.infra`` implements them, so infra\n# sits outside this order; ``infra-inverted`` and ``memory-forbidden``\n# below pin both directions.\nname = \"Layered architecture\"\ntype = \"layers\"\nlayers = [\n    \"everos.entrypoints\",\n    \"everos.service\",\n    \"everos.memory\",\n]\n\n[[tool.importlinter.contracts]]\n# Entry points translate a protocol (HTTP, CLI, TUI) into facade calls and\n# back. Request / response DTOs and error types reach them through the\n# ``everos.service`` facade or ``everos.core``; nothing below the service is\n# theirs to import. Direct imports only: an entry point reaching the domain\n# *through* the service is the point.\nname = \"entrypoints-forbidden: entry points import the service, not what it wires\"\ntype = \"forbidden\"\nsource_modules = [\"everos.entrypoints\"]\nforbidden_modules = [\n    \"everos.memory\",\n    \"everos.infra\",\n    \"everos.component\",\n    \"everalgo\",\n]\nallow_indirect_imports = true\n\n[[tool.importlinter.contracts]]\nname = \"infra-inverted: infra reaches the domain only through its ports\"\ntype = \"forbidden\"\nsource_modules = [\"everos.infra\"]\nforbidden_modules = [\n    \"everos.memory.extract\",\n    \"everos.memory.get\",\n    \"everos.memory.custom_instructions\",\n    \"everos.memory.reflection\",\n    \"everos.memory.search\",\n    \"everos.memory.strategies\",\n    \"everos.memory._partition_locks\",\n    \"everos.service\",\n    \"everos.entrypoints\",\n]\n\n[[tool.importlinter.contracts]]\nname = \"memory-forbidden: the domain does not import infra\"\ntype = \"forbidden\"\nsource_modules = [\"everos.memory\"]\nforbidden_modules = [\"everos.infra\"]\n\n[[tool.importlinter.contracts]]\nname = \"core-forbidden: core and config depend on nothing above them\"\ntype = \"forbidden\"\nsource_modules = [\"everos.core\", \"everos.config\"]\nforbidden_modules = [\n    \"everos.component\",\n    \"everos.memory\",\n    \"everos.service\",\n    \"everos.entrypoints\",\n    \"everos.infra\",\n]\n\n[[tool.importlinter.contracts]]\nname = \"component-forbidden: injectable providers depend on no layer\"\ntype = \"forbidden\"\nsource_modules = [\"everos.component\"]\nforbidden_modules = [\n    \"everos.memory\",\n    \"everos.service\",\n    \"everos.entrypoints\",\n    \"everos.infra\",\n]\n\n[[tool.importlinter.contracts]]\nname = \"mappers-pure: algo <-> domain mapping does no IO\"\ntype = \"forbidden\"\nsource_modules = [\"everos.memory.mappers\"]\nforbidden_modules = [\n    \"everos.infra\",\n    \"everos.component\",\n    \"everos.service\",\n]\n\n[[tool.importlinter.contracts]]\nname = \"Subpackage internals are private\"\ntype = \"forbidden\"\nsource_modules = [\"everos.service\", \"everos.memory\", \"everos.entrypoints\"]\n# `**` matches any descendant (writer.py, reader.py, sub.foo.bar, ...).\n# Public API must be reached via the subpackage `__init__.py`.\nforbidden_modules = [\n    \"everos.infra.persistence.markdown.**\",\n    \"everos.infra.persistence.lancedb.**\",\n    \"everos.infra.persistence.sqlite.**\",\n    \"everos.infra.persistence.index.**\",\n    \"everos.infra.persistence.records.**\",\n    \"everos.infra.persistence.milvus.**\",\n    \"everos.infra.cascade.**\",\n]\n# `forbidden` contracts run a *transitive closure* — any path from a\n# source module to a forbidden module fails the check, even when the\n# source only imports the subpackage top-level. The whitelist below\n# carves out **intra-subpackage wiring**: each storage subpackage's\n# own ``__init__.py`` imports its own ``tables`` / ``repos`` / manager\n# children to assemble the public API surface that outer layers reach.\n# These edges are normal Python package wiring, *not* a privacy\n# breach — without these ignores, even a legitimate\n# ``from everos.infra.persistence.sqlite import X`` would be punished\n# because the transitive scan walks one hop further into the package.\n#\n# Direct imports from outer layers into a subpackage internal module\n# (e.g. ``from everos.infra.persistence.sqlite._tables import X`` written\n# in ``service`` or ``entrypoints``) remain blocked — that edge is not\n# in this whitelist.\n#\n# Two edges below are *not* intra-subpackage wiring: ``lancedb -> records``\n# and ``index -> records``.\n# ``records/`` holds the table declarations every index backend reads\n# (TABLE_NAME / BM25_FIELDS / PRIMARY_KEY); it is the one shared schema\n# module inside ``persistence/`` (docs/architecture.md, dependency table).\nignore_imports = [\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite._tables\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite._repos\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite.sqlite_manager\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite.repositories\",\n    \"everos.infra.persistence.lancedb -> everos.infra.persistence.records\",\n    \"everos.infra.persistence.lancedb -> everos.infra.persistence.lancedb._repos\",\n    \"everos.infra.persistence.lancedb -> everos.infra.persistence.lancedb.lancedb_manager\",\n    \"everos.infra.persistence.lancedb -> everos.infra.persistence.lancedb.backend\",\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown._mds\",\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown._writers\",\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown._readers\",\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown.stores\",\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown.knowledge_store\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite.stores\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite.knowledge_catalog\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.maintenance\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.vector_projection\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.vector_backfill\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index._provenance\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.predicate\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.protocols\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.schema\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.derived_index\",\n    \"everos.infra.persistence.index -> everos.infra.persistence.index.repositories\",\n    # The storage factories are persistence's own wiring: they build the\n    # configured engine's backend (Milvus only when selected, so pymilvus\n    # stays an optional extra) and the domain's index adapters over it.\n    \"everos.infra.persistence.factories -> everos.infra.persistence.index.adapters\",\n    \"everos.infra.persistence.factories -> everos.infra.persistence.milvus\",\n    # Persistence primitives moved out of ``core`` (stage 2a): each storage\n    # subpackage facade re-exports its own ``base`` primitives, and\n    # ``records`` re-exports the base table it shares with every backend.\n    \"everos.infra.persistence.markdown -> everos.infra.persistence.markdown._base\",\n    \"everos.infra.persistence.sqlite -> everos.infra.persistence.sqlite._base\",\n    \"everos.infra.persistence.lancedb -> everos.infra.persistence.lancedb._base\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.index_record\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.base\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.vector\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records._parent_type\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records._provenance_key\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.agent_case\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.agent_skill\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.atomic_fact\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.episode\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.foresight\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.knowledge_topic\",\n    \"everos.infra.persistence.records -> everos.infra.persistence.records.user_profile\",\n    # The cascade facade assembles its public surface from its own modules.\n    \"everos.infra.cascade -> everos.infra.cascade._worker\",\n    \"everos.infra.cascade -> everos.infra.cascade.admin\",\n    \"everos.infra.cascade -> everos.infra.cascade.orchestrator\",\n    \"everos.infra.cascade -> everos.infra.cascade.registry\",\n]\n\n[[tool.importlinter.contracts]]\n# The facade and the router resolve a configured backend, so they import the\n# engine packages by design. The port definitions must not: the moment protocols or\n# schema knows a concrete engine, \"portable\" stops being checkable and the\n# next adapter inherits whatever leaked in. This is the rule that keeps the\n# split from eroding -- moving files alone does not stop anyone moving them\n# back.\nname = \"Derived-index ports know no concrete backend\"\ntype = \"forbidden\"\nsource_modules = [\n    \"everos.infra.persistence.index.protocols\",\n    \"everos.infra.persistence.index.schema\",\n    \"everos.infra.persistence.index.vector_projection\",\n    \"everos.memory.ports\",\n]\nforbidden_modules = [\n    \"everos.infra.persistence.lancedb\",\n    \"everos.infra.persistence.milvus\",\n]\n\n[[tool.importlinter.contracts]]\n# The record models declare columns, keys and which columns are embeddings;\n# every backend derives its physical schema from them through ``schema_for``.\n# The moment a record imports an engine (or its storage format), the\n# declarations stop being shared and the vector width can creep back into\n# import time (issue #476). Indirect imports are checked, so a helper module\n# cannot smuggle an engine in either.\nname = \"records-neutral: record declarations know no index backend\"\ntype = \"forbidden\"\nsource_modules = [\"everos.infra.persistence.records\"]\nforbidden_modules = [\n    \"everos.infra.persistence.lancedb\",\n    \"everos.infra.persistence.milvus\",\n    \"lancedb\",\n    \"pymilvus\",\n    \"pyarrow\",\n]\n\n[[tool.importlinter.contracts]]\nname = \"OME does not depend on service/entrypoints or sibling infra subpackages\"\ntype = \"forbidden\"\nsource_modules = [\"everos.infra.ome\"]\nforbidden_modules = [\n    \"everos.infra.persistence\",\n    \"everos.service\",\n    \"everos.entrypoints\",\n]\n\n[[tool.importlinter.contracts]]\n# The domain declares the types OME schedules (events, triggers, gates,\n# StrategySpec) in ``everos.memory.ports``; OME imports those and nothing\n# else of the domain. Direct imports only: the ports themselves reach\n# ``memory.models`` (and ``memory.deps`` for an annotation), which OME\n# never touches by name.\nname = \"ome-ports-only: OME reaches the domain only through its ports\"\ntype = \"forbidden\"\nsource_modules = [\"everos.infra.ome\"]\nforbidden_modules = [\n    \"everos.memory._partition_locks\",\n    \"everos.memory.deps\",\n    \"everos.memory.events\",\n    \"everos.memory.extract\",\n    \"everos.memory.get\",\n    \"everos.memory.mappers\",\n    \"everos.memory.models\",\n    \"everos.memory.custom_instructions\",\n    \"everos.memory.reflection\",\n    \"everos.memory.search\",\n    \"everos.memory.strategies\",\n]\nallow_indirect_imports = true\n\n[[tool.importlinter.contracts]]\n# The service layer has one assembler: ``service.bootstrap`` builds every\n# adapter and provider and injects them, so the use-case modules depend on\n# ports and protocols only. Direct imports only -- a use case reaching\n# ``bootstrap`` is the facade, not a bypass. A component protocol is\n# imported under ``TYPE_CHECKING`` (excluded above), which is what keeps\n# ``component.*.protocol`` usable here.\nname = \"service-usecases-forbidden: only the bootstrap builds adapters\"\ntype = \"forbidden\"\nsource_modules = [\"everos.service\"]\nforbidden_modules = [\n    \"everos.infra\",\n    \"everos.component.embedding\",\n    \"everos.component.llm\",\n    \"everos.component.parser\",\n    \"everos.component.rerank\",\n    \"everos.component.tokenizer\",\n]\nallow_indirect_imports = true\nignore_imports = [\n    \"everos.service.bootstrap -> everos.infra.**\",\n    \"everos.service.bootstrap -> everos.component.**\",\n]\n\n[[tool.importlinter.contracts]]\n# Logging, tracing and metrics are reached through ``everos.core.observability``\n# only: the backends are swapped where they are configured, not where they\n# are called. ``core`` itself is the facade, so it is not a source here.\nname = \"no-bypass-facade: business layers log and trace through core.observability\"\ntype = \"forbidden\"\nsource_modules = [\n    \"everos.entrypoints\",\n    \"everos.service\",\n    \"everos.memory\",\n    \"everos.infra\",\n]\nforbidden_modules = [\"structlog\", \"logging\", \"opentelemetry\"]\nallow_indirect_imports = true\n\n[dependency-groups]\ndev = [\n    \"ruff>=0.8.0\",\n    \"pytest>=8.4.0\",\n    \"pytest-asyncio>=1.1.0\",\n    \"pytest-cov>=6.0.0\",\n    \"pytest-rerunfailures>=15.0\",\n    \"import-linter>=2.0\",\n    \"pre-commit>=4.0.0\",\n    \"ipdb>=0.13.13\",\n    \"pyinstrument>=5.0.0\",\n    # Tracing tests must actually run (no skip-when-absent), so the optional\n    # [otel] stack is always present in the dev / CI environment.\n    \"opentelemetry-sdk>=1.27.0\",\n    \"opentelemetry-exporter-otlp-proto-http>=1.27.0\",\n    \"pymilvus>=3.0.0\",\n    \"hypothesis>=6.100\",\n]\n"
